// El envío está en curso (cuenta para el límite por minuto del remitente).
func (q *Queries) ReservarEnvio(ctx context.Context, arg ReservarEnvioParams) error {
	_, err := q.db.Exec(ctx, reservarEnvio, arg.EnviadoEn, arg.ID)
	return err
}

